        return AllowlistFacts::default();
    }
    AllowlistFacts {
        is_allowlisted: true,
        added_by: parse_dbg_opt_string(map.get(&format!("{prefix}_added_by"))),
        reason: parse_dbg_opt_string(map.get(&format!("{prefix}_reason"))),
